// HrSWInstalledTableKey is the decoded INDEX of one hrSWInstalledTable row, one field per
// part in INDEX order. It is comparable and usable as a map key.
type HrSWInstalledTableKey struct {
	HrSWInstalledIndex int32
}

var hrSWInstalledTableIndexShapes = []snmp.IndexShape{{Kind: snmp.IndexInteger}}

// decodeHrSWInstalledTableKey decodes the instance suffix of one hrSWInstalledTable row. ok is false
// when the suffix does not match the declared INDEX; the key is then zero.
func decodeHrSWInstalledTableKey(idx snmp.OID) (HrSWInstalledTableKey, bool) {
	var parts [1]snmp.IndexValue
	if !snmp.DecodeIndexInto(parts[:], idx, hrSWInstalledTableIndexShapes) {
		return HrSWInstalledTableKey{}, false
	}
	return HrSWInstalledTableKey{HrSWInstalledIndex: int32(parts[0].Integer)}, true
}

// HrSWInstalledTableRow is one table row; KeyValid reports index validity, use Observed for field presence, and concurrent reads are safe.
type HrSWInstalledTableRow struct {
	Key                HrSWInstalledTableKey
	keyValid           bool
	HrSWInstalledIndex int32
	HrSWInstalledName  []byte
	HrSWInstalledID    snmp.OID
	HrSWInstalledType  HrSWInstalledTypeValue
	HrSWInstalledDate  time.Time
	observed           [1]uint64
}

// KeyValid reports whether Key decoded from the row index.
func (r HrSWInstalledTableRow) KeyValid() bool {
	return r.keyValid
}

// Observed reports whether col supplied this row field, including a zero value.
func (r HrSWInstalledTableRow) Observed(col snmp.AnyColumn) bool {
	return snmp.ColumnObserved(r.observed[:], hrSWInstalledTableColumns, col)
}

// HrSWInstalledTableWalker streams one table walk; its zero value is unusable, and Err/Close are safe concurrently.
type HrSWInstalledTableWalker struct {
	snmp.TableWalker[HrSWInstalledTableRow]
}
type hrSWInstalledTableT struct {
	snmp.Table[HrSWInstalledTableRow, *HrSWInstalledTableWalker]
}

// HrSWInstalledTable is the descriptor for the hrSWInstalledTable table.
var HrSWInstalledTable = hrSWInstalledTableT{Table: snmp.NewTable("hrSWInstalledTable", hrSWInstalledTableColumns, func(idx snmp.OID, row *HrSWInstalledTableRow) {
	row.Key, row.keyValid = decodeHrSWInstalledTableKey(idx)
}, func(row *HrSWInstalledTableRow, ordinal int, rv snmp.RawVarBind) error {
	switch ordinal {
	case 0:
		return snmp.DecodeColumn(rv, HrSWInstalledIndex, &row.HrSWInstalledIndex, row.observed[:])
	case 1:
		return snmp.DecodeColumn(rv, HrSWInstalledName, &row.HrSWInstalledName, row.observed[:])
	case 2:
		return snmp.DecodeColumn(rv, HrSWInstalledID, &row.HrSWInstalledID, row.observed[:])
	case 3:
		return snmp.DecodeColumn(rv, HrSWInstalledType, &row.HrSWInstalledType, row.observed[:])
	case 4:
		return snmp.DecodeColumn(rv, HrSWInstalledDate, &row.HrSWInstalledDate, row.observed[:])
	}
	return nil
}, func(tw snmp.TableWalker[HrSWInstalledTableRow]) *HrSWInstalledTableWalker {
	return &HrSWInstalledTableWalker{TableWalker: tw}
})}

// Descriptor returns the table identity, change indicator, and row-key type.
func (hrSWInstalledTableT) Descriptor() snmp.TableDescriptor {
	return snmp.TableDescriptor{
		Indicator: HrSWInstalledTableIndicator,
		KeyType:   "HrSWInstalledTableKey",
		Root:      snmp.MustOID(1, 3, 6, 1, 2, 1, 25, 6, 3),
	}
}

// decodeHrSWInstalledTableRow decodes one row of HrSWInstalledTable from the supplied
// VarBinds. Each VarBind's OID determines which row field it populates
// (via the column's last sub-id). VarBinds with unknown column-ids are
// ignored. Absent columns leave their field at its zero value.
func decodeHrSWInstalledTableRow(idx snmp.OID, vbs []snmp.VarBind) (HrSWInstalledTableRow, error) {
	var row HrSWInstalledTableRow
	row.Key, row.keyValid = decodeHrSWInstalledTableKey(idx)

	for _, vb := range vbs {
		o := vb.GetHeader().OID
		if o.Len() == 0 {
			continue
		}
		entryLen := snmp.MustOID(1, 3, 6, 1, 2, 1, 25, 6, 3, 1).Len()
		if o.Len() <= entryLen {
			continue
		}
		colID := o.At(entryLen)
		switch colID {
		case 1:
			dv, derr := HrSWInstalledIndex.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.HrSWInstalledIndex = dv
			row.observed[0] |= 1 << 0
		case 2:
			dv, derr := HrSWInstalledName.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.HrSWInstalledName = dv
			row.observed[0] |= 1 << 1
		case 3:
			dv, derr := HrSWInstalledID.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.HrSWInstalledID = dv
			row.observed[0] |= 1 << 2
		case 4:
			dv, derr := HrSWInstalledType.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.HrSWInstalledType = dv
			row.observed[0] |= 1 << 3
		case 5:
			dv, derr := HrSWInstalledDate.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.HrSWInstalledDate = dv
			row.observed[0] |= 1 << 4
		}
	}

	return row, nil
}

// equalHrSWInstalledTableRow compares two HrSWInstalledTableRow values for equality.
// Used by [snmp.Watcher] to compute ChangeKindModified emits. Field-by-
// field with the type-appropriate comparator (bytes.Equal for []byte,
// OID.Equal for OID, time.Time.Equal for time.Time, == for everything else).
func equalHrSWInstalledTableRow(a HrSWInstalledTableRow, b HrSWInstalledTableRow) bool {
	return a.Key == b.Key && a.keyValid == b.keyValid && a.observed == b.observed && a.HrSWInstalledIndex == b.HrSWInstalledIndex && bytes.Equal(a.HrSWInstalledName, b.HrSWInstalledName) && a.HrSWInstalledID.Equal(b.HrSWInstalledID) && a.HrSWInstalledType == b.HrSWInstalledType && a.HrSWInstalledDate.Equal(b.HrSWInstalledDate)
}

// mergeHrSWInstalledTableRow merges the values decoded from vbs into dst, leaving fields
// whose columns are not present in vbs unchanged. Used by [snmp.Watcher]
// to maintain per-row state under partial-column fetches (Counter-tier,
// Static-tier). Best-effort: individual VarBind decode failures are
// silently skipped rather than propagated, because partial-fetch ticks
// surface transient errors through [snmp.Watcher.LastTickErr] at the
// call-site granularity rather than per-VarBind.
func mergeHrSWInstalledTableRow(dst *HrSWInstalledTableRow, vbs []snmp.VarBind) {
	for _, vb := range vbs {
		o := vb.GetHeader().OID
		if o.Len() == 0 {
			continue
		}
		entryLen := snmp.MustOID(1, 3, 6, 1, 2, 1, 25, 6, 3, 1).Len()
		if o.Len() <= entryLen {
			continue
		}
		colID := o.At(entryLen)
		switch colID {
		case 1:
			dv, derr := HrSWInstalledIndex.Decode(vb)
			if derr == nil {
				dst.HrSWInstalledIndex = dv
				dst.observed[0] |= 1 << 0
			}
		case 2:
			dv, derr := HrSWInstalledName.Decode(vb)
			if derr == nil {
				dst.HrSWInstalledName = dv
				dst.observed[0] |= 1 << 1
			}
		case 3:
			dv, derr := HrSWInstalledID.Decode(vb)
			if derr == nil {
				dst.HrSWInstalledID = dv
				dst.observed[0] |= 1 << 2
			}
		case 4:
			dv, derr := HrSWInstalledType.Decode(vb)
			if derr == nil {
				dst.HrSWInstalledType = dv
				dst.observed[0] |= 1 << 3
			}
		case 5:
			dv, derr := HrSWInstalledDate.Decode(vb)
			if derr == nil {
				dst.HrSWInstalledDate = dv
				dst.observed[0] |= 1 << 4
			}
		}
	}
}

